}

.bg-size-custom {
    background-image: url('https://images.unsplash.com/photo-1542831371-29b0f74f9713?w=400');
    background-size: 200px 100px;
    background-repeat: repeat;
    background-color: #f8f9fa;
    padding: 30px;
    margin: 10px 0;
    border-radius: 8px;
    text-align: center;
    min-height: 120px;
}

/* BACKGROUND ATTACHMENT EXAMPLES */
.bg-attachment-scroll {
    background-color: #3498db;
    color: white;
    padding: 20px;
    margin: 10px 0;
    border-radius: 8px;
}

.bg-attachment-fixed {
    background-image: url('https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=400');
    background-attachment: fixed;
    background-size: cover;
    background-position: center;
    color: white;
    padding: 40px;
    margin: 10px 0;
    border-radius: 8px;
    text-align: center;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.7);
    min-height: 150px;
}

/* MULTIPLE BACKGROUNDS */
.bg-multiple {
    background:
        url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="30" height="30" viewBox="0 0 30 30"><circle cx="15" cy="15" r="3" fill="white" opacity="0.5"/></svg>'),
        linear-gradient(45deg, #e74c3c, #3498db);
    background-size: 30px 30px, cover;
    background-position: 0 0, center;
    color: white;
    padding: 40px;
    margin: 10px 0;
    border-radius: 8px;
    text-align: center;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.7);
    min-height: 100px;
}

/* COLOR SCHEMES */
.color-scheme {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 10px;
    margin: 20px 0;
}

.color-scheme>div {
    padding: 20px;
    text-align: center;
    font-weight: bold;
    border-radius: 8px;
    color: white;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5);
}

.scheme-primary {
    background-color: #007bff;
}

.scheme-secondary {
    background-color: #6c757d;
}

.scheme-success {
    background-color: #28a745;
}

.scheme-warning {
    background-color: #ffc107;
    color: #212529;
    text-shadow: none;
}

.scheme-danger {
    background-color: #dc3545;
}

.scheme-info {
    background-color: #17a2b8;
}

.scheme-light {
    background-color: #f8f9fa;
    color: #212529;
    text-shadow: none;
    border: 1px solid #dee2e6;
}

.scheme-dark {
    background-color: #343a40;
}

/* ADVANCED COLOR TECHNIQUES */
.color-advanced {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 15px;
    margin: 20px 0;
}

.hover-color {
    background-color: #3498db;
    color: white;
    padding: 20px;
    text-align: center;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    font-weight: bold;
}

.hover-color:hover {
    background-color: #e74c3c;
    transform: scale(1.05);
}

.shadow-color {
    background-color: white;
    color: #2c3e50;
    padding: 20px;
    text-align: center;
    border-radius: 8px;
    font-weight: bold;
    box-shadow:
        0 4px 8px rgba(52, 152, 219, 0.3),
        0 6px 20px rgba(155, 89, 182, 0.3);
}

.border-color {
    background-color: #f8f9fa;
    color: #2c3e50;
    padding: 20px;
    text-align: center;
    border-radius: 8px;
    font-weight: bold;
    border: 4px solid transparent;
    background-clip: padding-box;
    position: relative;
}

.border-color::before {
    content: '';
    position: absolute;
    top: -4px;
    left: -4px;
    right: -4px;
    bottom: -4px;
    background: linear-gradient(45deg, #e74c3c, #f39c12, #f1c40f, #27ae60, #3498db, #9b59b6);
    border-radius: 12px;
    z-index: -1;
}

.text-gradient {
    background: linear-gradient(45deg, #e74c3c, #f39c12, #f1c40f, #27ae60, #3498db, #9b59b6);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    padding: 20px;
    text-align: center;
    font-weight: bold;
    font-size: 18px;
    background-color: white;
    border-radius: 8px;
}

