/* RESET & BASE STYLES */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    line-height: 1.6;
    color: #333;
    background-color: #f8f9fa;
}

img {
    max-width: 100%;
    height: auto;
}

a {
    text-decoration: none;
    color: inherit;
    transition: all 0.3s ease;
}

ul {
    list-style: none;
}

/* UTILITY CLASSES */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.section {
    padding: 80px 0;
}

.section-title {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 60px;
    color: #2c3e50;
    position: relative;
}

.section-title::after {
    content: '';
    position: absolute;
    bottom: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 80px;
    height: 3px;
    background: linear-gradient(45deg, #3498db, #e74c3c);
    border-radius: 2px;
}

.highlight {
    background: linear-gradient(120deg, #a8edea 0%, #fed6e3 100%);
    padding: 2px 6px;
    border-radius: 4px;
    font-weight: 600;
}

/* HERO SECTION */
.hero-section {
    position: relative;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    overflow: hidden;
}

.hero-background {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(255,255,255,0.1)" stroke-width="1"/></pattern></defs><rect width="100" height="100" fill="url(%23grid)"/></svg>');
    opacity: 0.3;
}

.hero-content {
    text-align: center;
    color: white;
    z-index: 2;
    max-width: 800px;
    padding: 0 20px;
}

.hero-title {
    font-size: 4rem;
    font-weight: 700;
    margin-bottom: 20px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
    animation: fadeInUp 1s ease-out;
}

.hero-subtitle {
    font-size: 1.5rem;
    font-weight: 300;
    margin-bottom: 20px;
    opacity: 0.9;
    animation: fadeInUp 1s ease-out 0.2s both;
}

.hero-quote {
    font-size: 1.2rem;
    font-style: italic;
    margin-bottom: 40px;
    opacity: 0.8;
    animation: fadeInUp 1s ease-out 0.4s both;
}

.cta-button {
    display: inline-block;
    background: linear-gradient(45deg, #e74c3c, #f39c12);
    color: white;
    padding: 15px 30px;
    border-radius: 50px;
    font-weight: 600;
    font-size: 1.1rem;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
    transition: all 0.3s ease;
    animation: fadeInUp 1s ease-out 0.6s both;
}

.cta-button:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
}

/* NAVIGATION */
.navbar {
    position: fixed;
    top: 0;
    width: 100%;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    z-index: 1000;
    box-shadow: 0 2px 20px rgba(0, 0, 0, 0.1);
    transition: all 0.3s ease;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 70px;
}

.nav-brand {
    font-size: 1.5rem;
    font-weight: 700;
    color: #2c3e50;
}

.nav-menu {
    display: flex;
    gap: 30px;
}

.nav-link {
    color: #2c3e50;
    font-weight: 500;
    padding: 10px 0;
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background: linear-gradient(45deg, #3498db, #e74c3c);
    transition: width 0.3s ease;
}

.nav-link:hover::after {
    width: 100%;
}

/* MAIN CONTENT */
.main-content {
    margin-top: 70px;
}

/* ABOUT SECTION */
.about-section {
    background: white;
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: start;
}

.profile-card {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border-radius: 20px;
    padding: 30px;
    color: white;
    text-align: center;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
}

.profile-image img {
    width: 200px;
    height: 250px;
    object-fit: cover;
    border-radius: 15px;
    margin-bottom: 20px;
    border: 4px solid rgba(255, 255, 255, 0.2);
}

.profile-info h3 {
    font-size: 1.8rem;
    margin-bottom: 10px;
}

.profile-role {
    font-size: 1.1rem;
    opacity: 0.9;
    margin-bottom: 30px;
}

.profile-stats {
    display: flex;
    justify-content: space-around;
    margin-top: 30px;
}

.stat {
    text-align: center;
}

.stat-number {
    display: block;
    font-size: 2rem;
    font-weight: 700;
    color: #f39c12;
}

.stat-label {
    font-size: 0.9rem;
    opacity: 0.8;
}

.bio-content {
    padding: 20px 0;
}

.bio-text {
    margin-bottom: 40px;
}

.lead {
    font-size: 1.2rem;
    color: #2c3e50;
    margin-bottom: 20px;
    line-height: 1.8;
}

.bio-text p {
    margin-bottom: 15px;
    color: #5a6c7d;
    line-height: 1.7;
}

.personal-info h3 {
    color: #2c3e50;
    margin-bottom: 20px;
    font-size: 1.3rem;
}

.info-grid {
    display: grid;
    gap: 15px;
}

.info-item {
    display: flex;
    justify-content: space-between;
    padding: 12px 0;
    border-bottom: 1px solid #ecf0f1;
}

.info-label {
    font-weight: 600;
    color: #34495e;
}

.info-value {
    color: #5a6c7d;
}

.info-value a {
    color: #3498db;
}

.info-value a:hover {
    color: #e74c3c;
}

/* SKILLS SECTION */
.skills-section {
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
}

.skills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 40px;
}

.skill-category {
    background: white;
    padding: 40px 30px;
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.skill-category:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
}

.category-icon {
    font-size: 3rem;
    text-align: center;
    margin-bottom: 20px;
}

.skill-category h3 {
    text-align: center;
    color: #2c3e50;
    margin-bottom: 30px;
    font-size: 1.4rem;
}

.skill-list {
    display: grid;
    gap: 20px;
}

.skill-item {
    display: grid;
    gap: 8px;
}

.skill-name {
    font-weight: 600;
    color: #34495e;
}

.skill-bar {
    height: 8px;
    background: #ecf0f1;
    border-radius: 4px;
    overflow: hidden;
}

.skill-progress {
    height: 100%;
    background: linear-gradient(45deg, #3498db, #e74c3c);
    border-radius: 4px;
    transition: width 1s ease-in-out;
}

/* EXPERIENCE SECTION */
.experience-section {
    background: white;
}

.timeline {
    position: relative;
    max-width: 800px;
    margin: 0 auto;
}

.timeline::before {
    content: '';
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    width: 3px;
    height: 100%;
    background: linear-gradient(to bottom, #3498db, #e74c3c);
}

.timeline-item {
    position: relative;
    margin-bottom: 60px;
}

.timeline-item:nth-child(odd) .timeline-content {
    text-align: right;
    padding-right: 60px;
}

.timeline-item:nth-child(even) .timeline-content {
    margin-left: 50%;
    padding-left: 60px;
}

.timeline-dot {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    width: 20px;
    height: 20px;
    background: white;
    border: 4px solid #3498db;
    border-radius: 50%;
    z-index: 2;
}

.job-card {
    background: white;
    padding: 30px;
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: transform 0.3s ease;
}

.job-card:hover {
    transform: translateY(-5px);
}

.job-card.current {
    border-left: 5px solid #27ae60;
    background: linear-gradient(135deg, #f8fff8 0%, #e8f5e8 100%);
}

.job-header {
    margin-bottom: 15px;
}

.job-header h3 {
    color: #2c3e50;
    font-size: 1.3rem;
    margin-bottom: 8px;
}

.job-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
}

.company {
    color: #3498db;
    font-weight: 600;
}

.period {
    background: #ecf0f1;
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.9rem;
    color: #5a6c7d;
}

.job-description {
    color: #5a6c7d;
    margin-bottom: 20px;
    line-height: 1.6;
}

.achievement-list {
    display: grid;
    gap: 8px;
}

.achievement-list li {
    color: #34495e;
    padding-left: 20px;
    position: relative;
}

.achievement-list li::before {
    content: '✓';
    position: absolute;
    left: 0;
    color: #27ae60;
    font-weight: bold;
}

/* PORTFOLIO SECTION */
.portfolio-section {
    background: linear-gradient(135deg, #ffeaa7 0%, #fab1a0 100%);
}

.portfolio-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 40px;
}

.project-card {
    background: white;
    border-radius: 15px;
    overflow: hidden;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.project-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.15);
}

.project-card.featured {
    grid-column: span 2;
}

.project-image {
    position: relative;
    overflow: hidden;
    height: 250px;
}

.project-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.project-card:hover .project-image img {
    transform: scale(1.1);
}

.project-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.8);
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.project-card:hover .project-overlay {
    opacity: 1;
}

.project-links {
    display: flex;
    gap: 20px;
}

.project-link {
    background: white;
    color: #2c3e50;
    padding: 12px 24px;
    border-radius: 25px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.project-link:hover {
    background: #3498db;
    color: white;
    transform: translateY(-2px);
}

.project-content {
    padding: 30px;
}

.project-content h3 {
    color: #2c3e50;
    margin-bottom: 15px;
    font-size: 1.3rem;
}

.project-content p {
    color: #5a6c7d;
    margin-bottom: 20px;
    line-height: 1.6;
}

.tech-stack {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.tech-tag {
    background: linear-gradient(45deg, #3498db, #2c3e50);
    color: white;
    padding: 4px 12px;
    border-radius: 15px;
    font-size: 0.85rem;
    font-weight: 500;
}

.feature-list,
.highlight-list {
    display: grid;
    gap: 8px;
}

.feature-item,
.highlight-item {
    color: #27ae60;
    font-size: 0.9rem;
    font-weight: 500;
}

/* CONTACT SECTION */
.contact-section {
    background: white;
}

.contact-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
}

.contact-info h3 {
    color: #2c3e50;
    font-size: 2rem;
    margin-bottom: 20px;
}

.contact-intro {
    color: #5a6c7d;
    font-size: 1.1rem;
    margin-bottom: 40px;
    line-height: 1.7;
}

.contact-methods {
    display: grid;
    gap: 25px;
    margin-bottom: 40px;
}

.contact-item {
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 20px;
    background: #f8f9fa;
    border-radius: 10px;
    transition: all 0.3s ease;
}

.contact-item:hover {
    background: #e9ecef;
    transform: translateX(10px);
}

.contact-icon {
    font-size: 2rem;
    width: 60px;
    text-align: center;
}

.contact-details h4 {
    color: #2c3e50;
    margin-bottom: 5px;
}

.contact-details a {
    color: #3498db;
    font-weight: 500;
}

.contact-details a:hover {
    color: #e74c3c;
}

.social-links h4 {
    color: #2c3e50;
    margin-bottom: 15px;
}

.social-icons {
    display: flex;
    gap: 15px;
}

.social-link {
    background: linear-gradient(45deg, #667eea, #764ba2);
    color: white;
    padding: 12px 20px;
    border-radius: 25px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.social-link:hover {
    transform: translateY(-3px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

.social-link.linkedin:hover {
    background: #0077b5;
}

.social-link.github:hover {
    background: #333;
}

.social-link.instagram:hover {
    background: linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888);
}

.availability-card {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 40px;
    border-radius: 20px;
    text-align: center;
}

.availability-card h3 {
    margin-bottom: 25px;
    font-size: 1.5rem;
}

.status-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-bottom: 30px;
    font-weight: 600;
}

.status-dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: #27ae60;
    animation: pulse 2s infinite;
}

.service-list {
    margin-bottom: 25px;
    text-align: left;
}

.service-list h4 {
    margin-bottom: 15px;
    text-align: center;
}

.service-list ul {
    display: grid;
    gap: 10px;
}

.service-list li {
    padding-left: 5px;
}

.response-time {
    font-style: italic;
    opacity: 0.9;
}

/* FOOTER */
.footer {
    background: #2c3e50;
    color: white;
    padding: 60px 0 20px;
}

.footer-content {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 60px;
    margin-bottom: 40px;
}

.footer-brand h3 {
    margin-bottom: 10px;
    font-size: 1.5rem;
}

.footer-brand p {
    opacity: 0.8;
}

.footer-links {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 40px;
}

.footer-column h4 {
    margin-bottom: 20px;
    color: #3498db;
}

.footer-column ul {
    display: grid;
    gap: 10px;
}

.footer-column a {
    opacity: 0.8;
    transition: opacity 0.3s ease;
}

.footer-column a:hover {
    opacity: 1;
    color: #3498db;
}

.footer-bottom {
    border-top: 1px solid #34495e;
    padding-top: 20px;
    text-align: center;
}

.footer-bottom p {
    margin-bottom: 10px;
    opacity: 0.8;
}

.footer-note {
    font-size: 0.9rem;
    opacity: 0.6;
}

.back-to-top {
    color: #3498db;
    font-weight: 600;
    margin-top: 10px;
    display: inline-block;
}

.back-to-top:hover {
    color: #e74c3c;
}

/* ANIMATIONS */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes pulse {
    0% {
        box-shadow: 0 0 0 0 rgba(39, 174, 96, 0.7);
    }

    70% {
        box-shadow: 0 0 0 10px rgba(39, 174, 96, 0);
    }

    100% {
        box-shadow: 0 0 0 0 rgba(39, 174, 96, 0);
    }
}

/* RESPONSIVE DESIGN */
@media (max-width: 1024px) {
    .project-card.featured {
        grid-column: span 1;
    }

    .about-content {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .contact-content {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 40px;
    }
}

@media (max-width: 768px) {
    .hero-title {
        font-size: 2.5rem;
    }

    .hero-subtitle {
        font-size: 1.2rem;
    }

    .section {
        padding: 60px 0;
    }

    .section-title {
        font-size: 2rem;
    }

    .nav-menu {
        display: none;
    }

    .timeline::before {
        left: 20px;
    }

    .timeline-item:nth-child(odd) .timeline-content {
        margin-left: 50px;
        padding-right: 0;
        text-align: left;
    }

    .timeline-item:nth-child(even) .timeline-content {
        margin-left: 50px;
        padding-left: 0;
    }

    .timeline-dot {
        left: 20px;
    }

    .portfolio-grid {
        grid-template-columns: 1fr;
    }

    .skills-grid {
        grid-template-columns: 1fr;
    }

    .job-meta {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 15px;
    }

    .hero-title {
        font-size: 2rem;
    }

    .nav-container {
        padding: 0 15px;
    }

    .profile-stats {
        flex-direction: column;
        gap: 20px;
    }

    .social-icons {
        flex-direction: column;
    }
}
